import heapq

# Link-state routing: every router learns the whole map (who links to whom, at what cost)
# and runs Dijkstra's algorithm to find its cheapest path to every other router.
links = [("A", "B", 2), ("A", "C", 5), ("B", "C", 1), ("B", "D", 7), ("C", "D", 2), ("C", "E", 8), ("D", "E", 3)]
graph = {}
for x, y, cost in links:
    graph.setdefault(x, []).append((y, cost))
    graph.setdefault(y, []).append((x, cost))


def dijkstra(source):
    dist = {source: 0}
    first_hop = {source: None}
    queue = [(0, source, None)]
    done = set()
    while queue:
        d, node, hop = heapq.heappop(queue)
        if node in done:
            continue
        done.add(node)
        first_hop[node] = hop
        for neighbor, cost in sorted(graph[node]):
            new = d + cost
            if new < dist.get(neighbor, float("inf")):
                dist[neighbor] = new
                heapq.heappush(queue, (new, neighbor, hop or neighbor))
    return dist, first_hop


dist, hop = dijkstra("A")
print("router A's forwarding table")
print("destination  cost  next hop")
for node in sorted(dist):
    if node != "A":
        print(f"{node:11}  {dist[node]:>4}  {hop[node]}")

# The link C-D fails. Routers flood the news and everyone recomputes.
graph["C"] = [(n, c) for n, c in graph["C"] if n != "D"]
graph["D"] = [(n, c) for n, c in graph["D"] if n != "C"]
dist, hop = dijkstra("A")
print("\nafter link C-D fails:")
for node in ["D", "E"]:
    print(f"{node}: cost {dist[node]}, next hop {hop[node]}")

